package com.example.rokidgeminisecretary;
import android.content.*;import org.json.*;import java.io.*;import java.util.*;
/** Immutable original plus append-only personal corrections. No model or bridge writes. */
final class AnswerCorrections {
 static boolean eligible(JSONObject row){return row!=null&&row.optString("kind").matches("Gemini|直接回答|Assistant|トピック要約")&&row.optLong("time")>0&&!row.optString("message").trim().isEmpty();}
 static JSONObject source(JSONObject row)throws Exception{if(!eligible(row)||row.optString("message").length()>64000)throw new IOException("保存済みの回答を選んでください");String request=row.optString("requestId");if(!request.isEmpty()&&!TrackedWebRequest.validId(request))throw new IOException("回答IDを確認してください");return new JSONObject().put("kind",row.getString("kind")).put("time",row.getLong("time")).put("message",row.getString("message")).put("requestId",request).put("legacy",row.optBoolean("legacy"));}
 static String key(JSONObject row)throws Exception{return ReviewStore.hash(source(row));}
 static JSONObject store(Context c)throws Exception{try{if(ConversationWorkspace.file(c,"answer-corrections").getBaseFile().length()>8500000)throw new IOException("訂正の保存容量を確認してください");return ConversationWorkspace.read(c,"answer-corrections");}catch(FileNotFoundException absent){return new JSONObject().put("items",new JSONArray());}}
 static synchronized JSONObject view(Context c,JSONObject raw)throws Exception{JSONObject original=source(raw);String id=key(original);JSONArray rows=store(c).getJSONArray("items");for(int i=0;i<rows.length();i++)if(id.equals(rows.getJSONObject(i).getString("id")))return new JSONObject(rows.getJSONObject(i).toString());return new JSONObject().put("id",id).put("source",original).put("revision",0).put("corrections",new JSONArray());}
 static synchronized JSONArray list(Context c)throws Exception{JSONArray rows=store(c).getJSONArray("items"),out=new JSONArray();for(int i=rows.length()-1;i>=0;i--)out.put(new JSONObject(rows.getJSONObject(i).toString()));return out;}
 static synchronized JSONObject append(Context c,JSONObject raw,int revision,String changeId,String text)throws Exception{JSONObject original=source(raw);if(changeId==null||!changeId.matches("[a-f0-9-]{36}")||text==null||text.trim().isEmpty()||text.length()>2400||revision<0)throw new IOException("訂正は1〜2400文字で入力してください");String body=text.trim(),id=key(original);JSONObject store=store(c),entry=null;JSONArray rows=store.getJSONArray("items");for(int i=0;i<rows.length();i++)if(id.equals(rows.getJSONObject(i).getString("id")))entry=rows.getJSONObject(i);if(entry==null){if(rows.length()>=100)throw new IOException("訂正付き回答は100件までです。元の記録は保持しています");entry=view(c,original);rows.put(entry);}JSONArray changes=entry.getJSONArray("corrections");for(int i=0;i<changes.length();i++){JSONObject prior=changes.getJSONObject(i);if(changeId.equals(prior.getString("id"))){if(!body.equals(prior.getString("text")))throw new IOException("同じ訂正IDの内容が異なります。入力を残して開き直してください");return new JSONObject(entry.toString());}}if(entry.getInt("revision")!=revision)throw new IOException("ほかの画面で訂正が追加されています。入力を残し、最新の訂正を確認してください");if(changes.length()>=20)throw new IOException("1回答への訂正は20件までです");changes.put(new JSONObject().put("id",changeId).put("text",body).put("at",System.currentTimeMillis()));entry.put("revision",revision+1);if(store.toString().getBytes("UTF-8").length>8000000)throw new IOException("訂正の保存容量が上限です。元の記録は保持しています");ConversationWorkspace.write(c,"answer-corrections",store);return new JSONObject(entry.toString());}
 static JSONObject resolve(MainActivity owner,JSONObject raw)throws Exception{JSONObject original=source(raw);String id=key(original);JSONObject saved=view(owner,original);if(saved.optInt("revision")>0)return saved.getJSONObject("source");JSONArray history=owner.localRecordConversations();for(int i=0;i<history.length();i++){JSONObject candidate=history.getJSONObject(i);if(eligible(candidate)&&id.equals(key(candidate)))return source(candidate);}throw new IOException("元の回答が削除・更新されています。保存済み回答を開き直してください");}
 static JSONObject submit(MainActivity owner,JSONObject input)throws Exception{synchronized(LokiWebConsole.class){synchronized(MainActivity.class){JSONObject original=resolve(owner,input.getJSONObject("source"));return append(owner,original,input.getInt("revision"),input.getString("changeId"),input.getString("text"));}}}
 static String text(JSONObject entry){StringBuilder b=new StringBuilder(entry.optJSONObject("source").optBoolean("legacy")?"元の回答（更新前の保存履歴・抜粋。変更しません）\n":"元の回答（変更しません）\n").append(entry.optJSONObject("source").optString("message")).append("\n\n利用者の訂正（AIが確認した内容ではありません）");JSONArray rows=entry.optJSONArray("corrections");if(rows==null||rows.length()==0)b.append("\nまだ訂正はありません");for(int i=0;rows!=null&&i<rows.length();i++){JSONObject row=rows.optJSONObject(i);b.append("\n\n").append(i+1).append(". ").append(new java.util.Date(row.optLong("at"))).append("\n").append(row.optString("text"));}return b.toString();}
 private AnswerCorrections(){}
}
